//! P-PCTU, the loud half (ROADMAP §5.2 P-PCTU ; OP-L): `%u` / `%U` / `%z` / `%Z` of an argument with no
//! binary form — a `real`, a `string`, a class handle, a call returning `string` or with the implicit one-bit
//! return shape — and a `$fscanf` / `$sscanf` binary read the scan can reach are E3009 (IEEE 1800-2017
//! §21.2.1.2: the integer formats take an integral argument ; §21.3.4.3). The encoder is parked (§5.2 P-PCTU),
//! so every `%u` / `%z` that is not refused still writes nothing, as before.
//!
//! GENERATED by W/ppctu/r3/bin/genpins.py from the measured cells (each source verbatim): a `_loud` test's
//! cells are refused on every lane with CB3 v3's lines (W/ppctu/plan2) or this row's (W/ppctu/r3/cells) and fail
//! on PRE (01cac4b3) ; a `_stays` test's cells print PRE's items on every lane, before and after this row. Each cell is checked on native,
//! interp, vm, the JIT (with `--features jit`) and the staged chain: exit code, every `error[` / `fatal[` line,
//! the `<TAG>bytes</>` items of stdout and of the files it writes (raw bytes, `strbytes_util`).

mod strbytes_util;
use strbytes_util::{esc, lanes, Cell, Mode};

struct Want {
    name: &'static str,
    src: &'static str,
    rc: i32,
    errs: &'static [&'static str],
    out: Items,
    files: &'static [(&'static str, Items)],
}

type Items = &'static [(&'static str, &'static [u8])];

/// `<TAG>bytes</>` items, sorted (stdout and stderr interleave differently per lane).
fn items(b: &[u8]) -> Vec<(String, Vec<u8>)> {
    let mut v = Vec::new();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'<' {
            let t = b[i + 1..]
                .iter()
                .take_while(|c| c.is_ascii_alphanumeric() || **c == b'_' || **c == b'.')
                .count();
            if t > 0 && b.get(i + 1 + t) == Some(&b'>') {
                let s = i + 2 + t;
                if let Some(e) = b[s..].windows(3).position(|w| w == b"</>") {
                    let tag = String::from_utf8(b[i + 1..i + 1 + t].to_vec()).unwrap();
                    v.push((tag, b[s..s + e].to_vec()));
                    i = s + e + 3;
                    continue;
                }
            }
        }
        i += 1;
    }
    v.sort();
    v
}

fn show(v: &[(String, Vec<u8>)]) -> String {
    v.iter()
        .map(|(t, b)| format!("<{t}>{}", esc(b)))
        .collect::<Vec<_>>()
        .join(" ")
}

fn want_items(w: Items) -> Vec<(String, Vec<u8>)> {
    let mut v: Vec<_> = w.iter().map(|(t, b)| (t.to_string(), b.to_vec())).collect();
    v.sort();
    v
}

fn check_all(cells: &[Want]) {
    let mut bad = Vec::new();
    for w in cells {
        let c = Cell {
            src: w.src,
            inputs: &[],
            plus: None,
            mode: Mode::At,
            staged: true,
        };
        for r in lanes(&c) {
            let at = format!("{} [{}]", w.name, r.lane);
            if r.rc != Some(w.rc) {
                bad.push(format!("{at} exit {:?}, want {}", r.rc, w.rc));
            }
            let errs: Vec<String> = r
                .out
                .split(|&b| b == b'\n')
                .filter(|l| {
                    l.windows(6).any(|x| x == b"error[") || l.windows(6).any(|x| x == b"fatal[")
                })
                .map(|l| String::from_utf8_lossy(l).into_owned())
                .collect();
            if errs != w.errs {
                bad.push(format!(
                    "{at} error lines\n   got  {errs:?}\n   want {:?}",
                    w.errs
                ));
            }
            let (got, want) = (items(&r.out), want_items(w.out));
            if got != want {
                bad.push(format!(
                    "{at} stdout\n   got  {}\n   want {}",
                    show(&got),
                    show(&want)
                ));
            }
            for (f, fw) in w.files {
                let got = r.files.get(*f).map(|b| items(b));
                let want = want_items(fw);
                if got.as_ref() != Some(&want) {
                    bad.push(format!(
                        "{at} file {f}\n   got  {}\n   want {}",
                        got.map(|g| show(&g)).unwrap_or_else(|| "<missing>".into()),
                        show(&want)
                    ));
                }
            }
        }
    }
    assert!(
        bad.is_empty(),
        "{} mismatches:\n{}",
        bad.len(),
        bad.join("\n")
    );
}

