/// K3 (RULINGS-r3 C1, RULINGS-r4 N1): the scan gate's list of the conversions the scan reads
/// (sys_special.rs `scan_unformatted_spec`) equals the engine's (scan_arm.rs `scan_run`, the conversion
/// match), both read from the binary over every printable conversion byte and a closed scanset. The
/// engine side scans, per letter L, a token L converts followed by `" 7"` with `%*L%d` (`b` "1", `o` "7",
/// `d` "1", `h` `x` "f", `f` `e` `g` `t` "1.5", `v` "St1", `c` "A", `s` "ab", `m` "" (it reads nothing),
/// an upper-case letter its lower case's token, every other letter "1"): `1 7` where the scan reads `%L`
/// and goes on to `%d`, `0 0` where it stops at `%L`. The gate side refuses `%*L%u` exactly where its walk
/// goes past `%L` (and at `%*u` / `%*z` themselves, which the engine side cannot run: the gate refuses
/// them). A letter the engine starts to read (`%f`, `%v`) without joining the gate's list leaves a
/// reachable `%u` after it unrefused, and fails here.
#[test]
fn pctu_scan_gate_letters_match_engine() {
    use std::collections::BTreeSet;
    let mut letters: Vec<String> = (0x21u8..0x7f)
        .map(|c| c as char)
        .filter(|c| !"\"%*\\[0123456789".contains(*c))
        .map(String::from)
        .collect();
    letters.push("[1]".into());
    let binary: BTreeSet<String> = ["u", "U", "z", "Z"].iter().map(|s| s.to_string()).collect();
    // a token the letter converts (an upper-case letter takes its lower case's), then " 7"
    let token = |l: &str| -> &'static str {
        match l.to_ascii_lowercase().as_str() {
            "o" => "7",
            "h" | "x" => "f",
            "f" | "e" | "g" | "t" => "1.5",
            "v" => "St1",
            "c" => "A",
            "s" => "ab",
            "m" => "",
            _ => "1",
        }
    };
    let design = |conv: &str, rows: &[(usize, &String)]| -> String {
        let mut s = String::from("module top;\n  integer n; logic [31:0] x;\n  initial begin\n");
        for (k, l) in rows {
            let input = format!("{} 7", token(l));
            s += &format!(
                "    x = 0; n = $sscanf(\"{input}\", \"%*{l}{conv}\", x); $display(\"<L{k}>%0d %0d</>\", n, x);\n"
            );
        }
        s + "  end\nendmodule\n"
    };
    let run = |src: &str| {
        let c = Cell {
            src,
            inputs: &[],
            plus: None,
            mode: Mode::At,
            staged: false,
        };
        strbytes_util::one_shot(&c, "native", &[], false)
    };
    // engine side: every byte but the binary reads themselves
    let rows: Vec<(usize, &String)> = letters
        .iter()
        .enumerate()
        .filter(|(_, l)| !binary.contains(*l))
        .collect();
    let eng = run(&design("%d", &rows));
    let got = items(&eng.out);
    assert_eq!(
        eng.rc,
        Some(0),
        "engine side: {}",
        String::from_utf8_lossy(&eng.out)
    );
    assert_eq!(got.len(), rows.len(), "engine side: one count per letter");
    let engine: BTreeSet<String> = got
        .iter()
        .filter(|(_, v)| v == b"1 7")
        .map(|(t, _)| letters[t[1..].parse::<usize>().unwrap()].clone())
        .collect();
    assert!(
        got.iter().all(|(_, v)| v == b"1 7" || v == b"0 0"),
        "engine side: counts {}",
        show(&got)
    );
    assert!(
        engine.contains("d") && engine.contains("[1]"),
        "engine side reads nothing: {engine:?}"
    );
    // gate side: every byte, the refused lines' letters
    let all: Vec<(usize, &String)> = letters.iter().enumerate().collect();
    let gate_run = run(&design("%u", &all));
    let gate: BTreeSet<String> = String::from_utf8_lossy(&gate_run.out)
        .lines()
        .filter(|l| l.contains("error[VITA-E3009]") && l.contains("a binary read"))
        .map(|l| {
            let line: usize = l.split(':').nth(1).unwrap().parse().unwrap();
            letters[line - 4].clone()
        })
        .collect();
    let want: BTreeSet<String> = engine.union(&binary).cloned().collect();
    assert_eq!(
        gate, want,
        "gate letters (refused `%*L%u`) != the engine's read letters + u U z Z"
    );
}
